'use strict';
// Each page owns its report, filters and exports. The global report selector is replaced by an index.
const workflowStates=new Map();
Object.assign(accessParents,{flujo:'caja',resumen:'reportes',adquisiciones:'reportes',comparacion:'periodos'});
for(const [route,c]of Object.entries(WorkflowPolicy.routes))labels[route]=c.title;
function workflowState(route=appState.route){const saved=workflowStates.get(route)||{};const state=WorkflowPolicy.normalize(route,saved,appState.today);workflowStates.set(route,state);return state;}
function workflowDateLabel(c,s){if(c.snapshot)return c.kind==='adquisiciones'?'Acumulado histórico':(c.subject?'Saldos actuales':c.kind==='radar'?'Existencias actuales':'Situación actual')+' · '+fmtDate(appState.today);return s.period==='all'?'Periodo aplicado: todo el historial':'Periodo aplicado: '+fmtDate(s.start)+' al '+fmtDate(s.end);}
function workflowExportMenu(items){if(!items.length)return '';return `<div class="workflow-export"><button class="btn" data-action="x-workflow-export-menu" aria-expanded="false">${icon('download',16)}Exportar${icon('down',14)}</button><div class="workflow-export-options" role="group" aria-label="Opciones de exportación" hidden>${items.map(([label,action])=>button(label,action,'text')).join('')}</div></div>`;}
function workflowExports(route){const c=WorkflowPolicy.config(route),kind=workflowState(route).view,module=auditReportAccess[kind]||({adquisiciones:'reportes',operaciones:'reportes'}[kind])||'reportes';if(!allowed(module,'exportar'))return '';return workflowExportMenu([['CSV del listado','x-workflow-export-csv'],['Excel del listado','x-workflow-export-xls'],...(c.book?[['Libro detallado · Excel','x-workflow-export-book']]:[])]);}
function workflowActions(route){return (route==='compras'&&allowed('compras','crear')?pButton('Registrar compra','receive','primary','plus'):route==='ventas'&&allowed('pos','crear')?button('Nueva venta','goto-pos','primary','plus'):'')+workflowExports(route);}
function workflowFields(route,s){const c=WorkflowPolicy.config(route);if(s.view.endsWith('_aging'))return '';let html='';for(const field of c.fields){switch(field){
 case'query':html+=input(c.subject==='clientes'?'Buscar cliente o documento':c.subject==='proveedores'?'Buscar proveedor o documento':route==='compras'?'Buscar compra, factura o proveedor':route==='ventas'?'Buscar venta, cliente o pieza':'Buscar en el listado','query',s.query||'','search');break;
 case'status':{const options=c.subject?[['','Con saldo'],['Vencido','En mora'],['Por vencer','Vence en 7 días'],['Al día','Al día'],['Sin vencimiento','Sin vencimiento documentado'],['Alto riesgo','Alto riesgo'],['Sin saldo','Saldados'],['Todos','Todos los contactos']]:route==='radar'?[['','Todos'],['Agotado','Agotado'],['Crítico','Crítico'],['Alerta','Alerta'],['Ok','Disponible'],['Sin movimiento','Sin movimiento'],['Stock bajo','Stock bajo'],['Baja rotación','Baja rotación']]:[['','Todas'],['paid','Pagadas'],['pending','Pendientes'],['void','Anuladas'],...(route==='ventas'?[['layaway','Separes']]:[])];html+=select('Estado','status',options,s.status||'');break;}
 case'supplierId':html+=select('Proveedor','supplierId',[['','Todos los proveedores'],...data().suppliers.map(p=>[p.id,p.name])],s.supplierId||'');break;
 case'category':html+=select('Categoría','category',[['','Todas las categorías'],...data().categories],s.category||'');break;
 case'seller':html+=select('Vendedor','seller',[['','Todos los vendedores'],...[...new Map(data().sales.map(o=>[o.userId,o.cashier])).entries()]],s.seller||'');break;
 case'method':html+=select('Medio de pago','method',[['','Todos'],['cash','Efectivo'],['transfer','Transferencia'],['card','Tarjeta']],s.method||'');break;
 case'metric':html+=select('Ordenar por','metric',[['revenue','Ventas'],['qty','Cantidad'],['profit','Utilidad'],['margin','Margen']],s.metric||'revenue');break;
 case'limit':html+=select('Mostrar','limit',[[5,'Top 5'],[10,'Top 10'],[20,'Top 20'],[100,'Top 100'],['all','Todos']],s.limit||10);break;
 case'productId':html+=select('Producto','productId',[['','Seleccionar pieza'],...data().products.map(p=>[p.id,p.sku+' · '+p.name])],s.productId||'');break;
 case'sort':html+=select('Ordenar por','sort',[['stock_asc','Menor stock'],['stock_desc','Mayor stock'],['dias_asc','Menor cobertura'],['dias_desc','Mayor cobertura'],['nombre_asc','Nombre A–Z'],['nombre_desc','Nombre Z–A'],['default','Orden del catálogo']],s.sort||'stock_asc');break;
 case'accountId':html+=select('Cuenta','accountId',[['','Todas las cuentas'],['cash','Caja en efectivo'],...data().accounts.map(a=>[a.id,a.name])],s.accountId||'');break;
 }}return html;}
function workflowControls(route){const c=WorkflowPolicy.config(route),s=workflowState(route),fields=workflowFields(route,s);const custom=s.period==='custom';return `<section class="card workflow-controls">${c.views?`<div class="workflow-tabs" aria-label="Vistas de ${esc(c.title)}">${c.views.map(([kind,label])=>`<button class="btn ${s.view===kind?'primary':''}" data-action="x-workflow-view-${kind}" ${s.view===kind?'aria-current="page"':''}>${label}</button>`).join('')}</div>`:''}<form id="workflow-filters" class="card-body" data-route="${route}">${!c.snapshot?`<div class="workflow-period">${select('Periodo','period',WorkflowPolicy.presets,s.period)}<div class="workflow-custom-range" ${custom?'':'hidden'}>${input('Fecha inicial','start',s.start==='0001-01-01'?appState.today.slice(0,7)+'-01':s.start,'date',custom?'required':'')}${input('Fecha final','end',s.end,'date',custom?'required':'')}</div></div>`:''}${fields?'<div class="workflow-filter-fields">'+fields+'</div>':''}${!c.snapshot||fields?`<div class="workflow-filter-actions">${errorBox()}<button class="btn primary" type="submit">Aplicar filtros</button>${pButton('Restablecer','workflow-reset','text')}</div>`:''}<p class="workflow-period-caption">${esc(c.snapshot?(route==='radar'?'Existencias actuales · Rotación de los últimos 30 días':route==='adquisiciones'?'Adquisiciones documentadas · Acumulado histórico':workflowDateLabel(c,s)):workflowDateLabel(c,s))}</p>${c.subject?'<p class="muted workflow-context-note">'+(c.subject==='clientes'?'Esta sección muestra cuentas por cobrar a clientes. Los cobros por fecha se consultan en Abonos de clientes.':'Esta sección muestra cuentas por pagar a proveedores. Los pagos por fecha se consultan en Abonos a proveedores.')+'</p>':''}</form></section>`;}
function workflowView(route){const c=WorkflowPolicy.config(route);workflowState(route);return `<div data-workflow="${route}">${heading(c.title,c.description,workflowActions(route))}${workflowControls(route)}<section class="card workflow-results" id="workflow-results" aria-live="polite"><div class="card-body">Cargando ${esc(c.title.toLowerCase())}…</div></section></div>`;}
function workflowDebtTable(p,route){const supplier=route==='creditos',contacts=supplier?data().suppliers:data().customers;return table([...p.headers,'Acciones'],p.rows.map(row=>{const contact=contacts.find(c=>c.name===row[0]&&c.doc===row[1]);return `<tr>${row.map((v,i)=>`<td class="${typeof v==='number'?'num':''}">${formatCell(v,p.headers[i])}</td>`).join('')}<td>${contact?pButton('Ver cuenta','audit-statement-'+(supplier?'supplier-':'customer-')+contact.id,'text')+(!supplier&&row[3]>0?pButton('Preparar cobro','audit-collection-'+contact.id,'text'):''):''}</td></tr>`;}));}
function workflowPurchaseTable(p){return table(['Compra / Fecha','Proveedor','Mercancía','Total','Saldo','Estado','Acciones'],p.rows.map(row=>{const o=data().purchases.find(o=>o.id===row[1]);return `<tr><td><strong>${esc(row[1])}</strong><small>${fmtDate(row[0])} · ${esc(row[3])}</small></td><td>${esc(row[2])}</td><td>${esc(row[4])}<small>${Number(row[5]).toLocaleString('es-CO')} ${o?.measureType==='Pesaje'?'g':'un.'}</small></td><td class="num">${money(row[6])}</td><td class="num">${money(row[8])}</td><td>${badge(row[9],row[9]==='Anulada'?'warn':'')}</td><td>${o?button('Ver compra','purchase-'+o.id,'text')+(!o.voidedAt&&balance(o)>0&&allowed('compras','crear')?button('Abonar','purchase-payment-'+o.id,'text'):''):''}</td></tr>`;}));}
async function loadWorkflow(route){const target=document.querySelector('#workflow-results');if(!target)return;const c=WorkflowPolicy.config(route),s=workflowState(route),request=JSON.stringify(s);target.dataset.request=request;try{const query=WorkflowPolicy.query(route,s,appState.today),p=await api('/api/analytics?'+new URLSearchParams(query));if(!target.isConnected||target.dataset.request!==request)return;parityState.kind=p.kind;parityState.payload=p;let cards='',body='',charts='';
 if((route==='cartera'||route==='creditos')&&!p.kind.endsWith('_aging')){const total=p.rows.reduce((n,r)=>n+r[3],0),overdue=p.rows.reduce((n,r)=>n+r[4],0);cards=kpi(c.subject==='clientes'?'Clientes del listado':'Proveedores del listado',p.rows.length)+kpi('Saldo en el listado',money(total),'Deuda actual',true)+kpi('Vencido en el listado',money(overdue));body=workflowDebtTable(p,route);}
 else if(route==='compras'){const total=p.rows.filter(r=>r[9]!=='Anulada').reduce((n,r)=>n+r[6],0);cards=kpi('Compras del listado',p.rows.length)+kpi('Valor comprado',money(total),'Excluye anuladas',true);body=workflowPurchaseTable(p,route);}
 else if(route==='ventas'){body=auditedSalesTable(p.rows.map(r=>data().sales.find(o=>o.id===r[0])).filter(Boolean));}
 else{const summary=p.summary;if(summary){if(['general','finanzas','margen'].includes(p.kind))cards=kpi('Ventas netas',money(summary.netSales))+kpi('Costo histórico',money(summary.cost))+kpi('Utilidad bruta',money(summary.grossProfit))+kpi('Resultado operativo',money(summary.operatingProfit),'Después de gastos',true);else if(['compras','compras_dashboard'].includes(p.kind))cards=kpi('Valor comprado',money(summary.total))+kpi('Pagado',money(summary.paid))+kpi('Pendiente',money(summary.pending))+kpi('Compras',summary.orders);else if(p.kind.endsWith('_aging'))cards=kpi('Saldo actual',money(summary.balance))+kpi('Vencido',money(summary.overdue));else if(p.kind==='balance')cards=kpi('Activos',money(summary.assets))+kpi('Pasivos',money(summary.liabilities))+kpi('Patrimonio',money(summary.equity));else if(p.kind==='radar')cards=kpi('Críticos',summary.critical)+kpi('Alertas',summary.alert)+kpi('Agotados',summary.out)+kpi('Sin movimiento',summary.noMovement);else if(p.kind==='tendencia')cards=kpi('Cantidad vendida',Number(summary.qty).toLocaleString('es-CO'))+kpi('Ingresos del periodo',money(summary.revenue))+kpi('Stock actual',countLabel({measureType:summary.measureType},summary.stock));else if(p.kind==='flujo')cards=kpi('Entradas',money(summary.income))+kpi('Salidas',money(summary.outcome))+kpi('Flujo neto',money(summary.net));}
 const template=document.createElement('template');template.innerHTML=payloadTable(p);template.content.querySelector('.card-head')?.remove();body=template.innerHTML;charts=p.charts?.length?'<div class="grid-equal workflow-charts">'+p.charts.map(auditChart).join('')+'</div>':'';}
 target.innerHTML=(cards?'<div class="kpis workflow-kpis">'+cards+'</div>':'')+`<div class="card-head"><h2>${esc(c.views?.find(([kind])=>kind===p.kind)?.[1]||c.title)}</h2><small>${esc(workflowDateLabel(c,s))}</small></div>`+body+charts;
 }catch(e){if(target.isConnected)target.innerHTML=empty('No pudimos cargar esta sección',e.message,pButton('Reintentar','workflow-retry','primary'));}}
const workflowHubGroups=[['Clientes y cobros',[['cartera','Cartera y mora'],['abonos','Abonos de clientes']]],['Compras y proveedores',[['reportescompras','Análisis de compras'],['creditos','Créditos de proveedores'],['abonoscompras','Abonos a proveedores']]],['Resultados del negocio',[['resumen','Resumen comercial'],['finanzas','Finanzas y resultados'],['general','Reporte general'],['balance','Balance general'],['periodos','Comparativa mensual'],['comparacion','Comparación de periodos']]],['Inventario y ventas',[['ranking','Ventas por producto'],['tendencia','Tendencia por producto'],['radar','Radar de stock'],['margen','Margen real'],['adquisiciones','Costo de adquisición'],['ajustes','Ajustes de inventario']]],['Caja y bancos',[['cierres','Historial de caja'],['flujo','Flujo de fondos']]]];
function workflowHub(){return `<div data-workflow="reportes">${heading('Informes del negocio','Elige el área que quieres consultar. Cada informe conserva sus propios filtros.')}<div class="workflow-report-index">${workflowHubGroups.map(([title,items])=>{const visible=items.filter(([route])=>allowed(route)&&(!WorkflowPolicy.routes[route]?.private||isSuper()));return visible.length?`<section class="card"><div class="card-head"><h2>${title}</h2></div><div class="workflow-report-links">${visible.map(([route,label])=>`<a href="#${route}"><span>${label}</span>${icon('chevron',16)}</a>`).join('')}</div></section>`:'';}).join('')}</div></div>`;}
for(const route of Object.keys(WorkflowPolicy.routes))extraUI.views[route]=()=>workflowView(route);
extraUI.views.reportes=workflowHub;extraUI.views.informes=workflowHub;
function collapseWorkflowExports(main){const buttons=[...main.querySelectorAll('button[data-action]')].filter(b=>/^(?:x-)?export-(?:csv|xls)-|^x-audit-book-/.test(b.dataset.action));if(!buttons.length)return;const unique=new Map();for(const b of buttons){const action=b.dataset.action,key=action.replace(/^x-/,'');if(!unique.has(key))unique.set(key,[key.includes('book-')?'Libro detallado · Excel':key.startsWith('export-csv-')?'CSV del listado':'Excel del listado',action]);b.remove();}const holder=main.querySelector('.page-heading .actions');if(holder)holder.insertAdjacentHTML('beforeend',workflowExportMenu([...unique.values()]));}
const legacyWorkflowDecorate=extraUI.decorate;
extraUI.decorate=function(){legacyWorkflowDecorate();const host=document.querySelector('#main [data-workflow]');if(!host){collapseWorkflowExports(document.querySelector('#main'));return;}const route=host.dataset.workflow,main=document.querySelector('#main');main.querySelectorAll('.parity-links,.audit-controls,.audit-periods').forEach(el=>el.remove());host.querySelector('.page-heading .actions').innerHTML=WorkflowPolicy.routes[route]?workflowActions(route):'';if(WorkflowPolicy.routes[route])loadWorkflow(route);};
const legacyWorkflowSubmit=extraUI.submit;
extraUI.submit=async function(form,v){if(form.id==='workflow-filters'){const route=form.dataset.route,state=WorkflowPolicy.normalize(route,{...workflowState(route),...v},appState.today);workflowStates.set(route,state);render();return null;}return legacyWorkflowSubmit(form,v);};
const legacyWorkflowAction=extraUI.action;
extraUI.action=async function(a,t){if(a==='x-workflow-export-menu'){const owner=t.closest('.workflow-export'),menu=owner.querySelector('.workflow-export-options'),open=menu.hidden;document.querySelectorAll('.workflow-export-options').forEach(el=>el.hidden=true);document.querySelectorAll('[data-action=x-workflow-export-menu]').forEach(el=>el.setAttribute('aria-expanded','false'));menu.hidden=!open;if(open&&window.matchMedia('(max-width:767px)').matches)menu.style.setProperty('--workflow-menu-top',(t.getBoundingClientRect().bottom+8)+'px');t.setAttribute('aria-expanded',String(open));return;}
 if(a==='x-workflow-reset'){workflowStates.delete(appState.route);render();return;}if(a==='x-workflow-retry')return loadWorkflow(appState.route);
 if(a.startsWith('x-workflow-view-')){const route=appState.route,state=WorkflowPolicy.normalize(route,{...workflowState(route),view:a.slice(16)},appState.today);workflowStates.set(route,state);render();return;}
 if(a.startsWith('x-workflow-export-')){const route=appState.route,c=WorkflowPolicy.config(route),query=WorkflowPolicy.query(route,workflowState(route),appState.today,true),format=a.slice(18);if(format==='book'){const result=await api('/api/workbook?'+new URLSearchParams({...query,book:c.book}));return auditDownloadSheets(result);}
 const p=await api('/api/analytics?'+new URLSearchParams(query));return auditDownloadSheets({title:c.title,sheets:[{name:c.title,headers:p.headers,rows:p.rows}]},format);}
 return legacyWorkflowAction(a,t);};
document.addEventListener('change',e=>{if(!e.target.matches('#workflow-filters [name=period]'))return;const form=e.target.form,custom=e.target.value==='custom';form.querySelector('.workflow-custom-range').hidden=!custom;for(const name of ['start','end'])form.elements[name].required=custom;});
document.addEventListener('click',e=>{if(e.target.closest('[data-action=x-workflow-export-menu]'))return;document.querySelectorAll('.workflow-export-options').forEach(el=>el.hidden=true);document.querySelectorAll('[data-action=x-workflow-export-menu]').forEach(el=>el.setAttribute('aria-expanded','false'));});
document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;const opened=document.querySelector('.workflow-export-options:not([hidden])');if(opened){const owner=opened.closest('.workflow-export');opened.hidden=true;owner.querySelector('button').setAttribute('aria-expanded','false');owner.querySelector('button').focus();}});
